2490.,"llName, shouldBeEquipped, reason)\n    if not Runtime.enabled then return false end\n    local quiet = reason == \"Progression\" or reason == \"Isle 9 priority\"\n    if Internal.isCatchInProgress() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false end\n    if type(skillName) ~= \"string\" or skillName == \"\" then return false end\n    if shouldBeEquipped and Internal.isExcludedKaitunSkill(skillName) then\n        log(\"SKIP\", \"Excluded skill will not be equipped: \" .. tostring(skillName))\n        return false\n    end\n    if shouldBeEquipped and not hasSkill(skillName) then\n        log(\"BLOCK\", \"Cannot equip skill not confirmed Owned: \" .. tostring(skillName))\n        if not quiet then Internal.notify(\"Cannot equip: \" .. tostring(skillName) .. \" is not confirmed owned\", \"error\", 4) end\n        return false\n    end\n\n    local equipped = Internal.isSkillEquippedOnCurrentRod(skillName)\n    if equipped == (shouldBeEquipped == true) then return true end\n    local rodName = getCurrentRodName()\n    if rodName == \"\" or not hasRod(rodName) then\n        log(\"BLOCK\", \"Cannot change skill loadout: currently selected rod is not confirmed Owned\")\n        if not quiet then Internal.notify(\"Skill loadout paused: no owned rod is selected\", \"warning\", 4) end\n        return false\n    end\n    local remote = getRemote(\"EquipSkill\")\n    if not (remote and remote:IsA(\"RemoteFunction\")) then\n        log(\"BLOCK\", \"Source-confirmed Events.EquipSkill RemoteFunction unavailable\")\n        if not quiet then Internal.notify(\"Skill equip failed: Events.EquipSkill is unavailable\", \"error\", 5) end\n        return false\n    end\n\n    -- Match the game's own inventory UI: InvokeServer(skillName), one argument only.\n    local sent, result = invokeRemote(\"EquipSkill\", skillName)\n    if not sent or not result then\n        log(\"BLOCK\", \"EquipSkill rejected for \" .. skillName .. \": \" .. tostring(result))\n        if not quiet then Internal.notify(\"Server rejected skill change: \" .. skillName, \"error\", 5) end\n        return false\n    end\n\n    local verified, actualKey = Internal.waitForSkillState(skillName, shouldBeEquipped, 3.5)\n    if not verified then\n        local action = shouldBeEquipped and \"equip\" or \"remove\"\n        log(\"BLOCK\", \"EquipSkill was accepted but slot data did not confirm \" .. action .. \" for \" .. skillName .. \" on rod \" .. tostring(rodName))\n        if not quiet then Internal.notify(\"Skill \" .. action .. \" not confirmed: \" .. skillName, \"warning\", 5) end\n        return false\n    end\n    if shouldBeEquipped then\n        log(\"STEP\", \"Skill equipped and verified: \" .. skillName .. \" on slot \" .. tostring(actualKey or \"?\"))\n        if not quiet then Internal.notify(\"Equipped \" .. skillName .. \" \u{2192} \" .. tostring(actualKey or \"slot confirmed\"), \"success\", 4) end\n    else\n        log(\"STEP\", \"Skill removed and verified: \" .. skillName)\n        if not quiet then Internal.notify(\"Removed unsuitable skill: \" .. skillName, \"warning\", 4) end\n    end\n    return true\nend\n\nInternal.equipSkillToSlot = function(skillName, key)\n    -- key is only the desired priority label; the actual game's EquipSkill remote has no slot argument.\n    if not Runtime.enabled or Internal.isCatchInProgress() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false end\n    if Internal.isExcludedKaitunSkill(skillName) then return false end\n    local equipped, actualKey = Internal.isSkillEquippedOnCurrentRod(skillName)\n    if equipped then\n        log(\"SKILL\", \"Already equipped and verified: \" .. skillName .. \" on \" .. tostring(actualKey))\n        return true\n    end\n    return Internal.toggleSkillState(skillName, true, key)\nend\n\n-- Progression skills use explicit priority slots (Z/X/C/V); other owned skills use the first open slot,\n-- or V when full, so they do not displace the early progression priorities.\nlocal function ensureSkillEquippedForUse(skillName)\n    if not Runtime.enabled or Internal.isCatchInProgress() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false end\n    if Internal.isExcludedKaitunSkill(skillName) then\n        log(\"SKIP\", \"User-excluded skill will not be selected for use: \" .. tostring(skillName))\n        return false\n    end\n    if not hasSkill(skillName) then\n        log(\"BLOCK\", \"Cannot prepare a skill that is not confirmed Owned: \" .. tostring(skillName))\n        return false\n    end\n    local equipped, actualKey = Internal.isSkillEquippedOnCurrentRod(skillName)\n    if equipped then\n        log(\"SKILL\", \"Skill already equipped on current rod: \" .. skillName .. \" -> \" .. tostring(actualKey))\n        return true\n    end\n    local preferredKey = nil\n    local family = skillFamilyKey(skillName)\n    if family == skillFamilyKey(\"Infinite Sky Ascension\") then preferredKey = \"Z\"\n    elseif family == skillFamilyKey(\"Phoenix Strike Art\") then preferredKey = \"X\"\n    elseif family == skillFamilyKey(\"Taijiquan Technique\") then preferredKey = \"C\" end\n    return Internal.equipSkillToSlot(skillName, preferredKey)\nend\n\nlocal function buySkillIfAffordable(skillName, minimumLevel)\n    if not Runtime.enabled then return false end\n    if isFishingActive() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false end\n\n    if hasSkill(skillName) then\n        local ownedName = getOwnedSkillName(skillName) or skillName\n        ensureSkillEquippedForUse(ownedName)\n        return true\n    end\n\n    local module = getSkillModule(skillName)\n    if not module then\n        log(\"SKIP\", \"skill module is not present in Info.Skill; not sending a guessed purchase: \" .. skillName)\n        return false\n    end\n    local purchaseSkillName = module.Name\n    local price, skillData = getSkillPrice(skillName)\n    if price == nil or price < 0 then\n        log(\"SKIP\", \"skill price is not source-confirmed; not sending a guessed purchase: \" .. purchaseSkillName)\n        return false\n    end\n\n    local dataLevel = skillData and tonumber(skillData.RequiredLevel or skillData.LevelRequired or skillData.UnlockLevel) or 0\n    local required = math.max(tonumber(minimumLevel) or 0, dataLevel)\n    if getLevel() < required then\n        log(\"BLOCK\", string.format(\"skill %s requires level %d; current level=%d\", skillName, required, getLevel()))\n        return false\n    end\n\n    local cash = getCash()\n    if cash < price then\n        log(\"BLOCK\", string.format(\"skill %s waiting for cash: %.0f / %.0f\", skillName, cash, price))\n        return false\n    end\n    if os.clock() - Runtime.lastSkillBuyAttempt < 8 then return false end\n    Runtime.lastSkillBuyAttempt = os.clock()\n\n    if not withNPCPurchase then\n        log(\"BLOCK\", \"NPC purchase helper is not ready; skipped skill: \" .. skillName)\n        return false\n    end\n\n    local success, detail = withNPCPurchase(\"LearnSkill\", \"Sage Yijiu\", \"BuySkill \" .. purchaseSkillName, function(atNpc)\n        if not Runtime.enabled then return false, \"Kaitun stopped before purchase\" end\n        if hasSkill(purchaseSkillName) then return true, \"already owned\" end\n\n        local sent, sendError = fireRemote(\"BuySkill\", purchaseSkillName)\n        if not sent then return false, tostring(sendError) end\n\n        local deadline = os.clock() + (atNpc and 7 or 1.5)\n        while os.clock() < deadline and Runtime.enabled do\n            if hasSkill(purchaseSkillName) then\n                return true, \"ownership verified\"\n            end\n            task.wait(0.25)\n        end\n        if hasSkill(purchaseSkillName) then return true, \"ownership verified\" end\n        return false, \"BuySkill was sent but Owned did not update; NPC/level/currency requirement may have rejected it\"\n    end)\n\n    if success and hasSkill(purchaseSkillName) then\n        local ownedName = getOwnedSkillName(purchaseSkillName) or purchaseSkillName\n        log(\"STEP\", string.format(\"Skill purchase CONFIRMED: %s (price %.0f; cash now %.0f)\", ownedName, price, getCash()))\n        local equipConfirmed = ensureSkillEquippedForUse(ownedName)\n        if equipConfirmed then\n            Internal.notify(\"Skill purchased and equipped: \" .. ownedName, \"success\", 5)\n        else\n            Internal.notify(\"Skill purchased: \" .. ownedName .. \" \u{2022} waiting for slot\", \"warning\", 5)\n        end\n        return true\n    end\n\n    log(\"BLOCK\", \"Skill purchase NOT confirmed for \" .. purchaseSkillName .. \": \" .. tostring(detail or \"unknown server response\"))\n    Internal.notify(\"Skill purchase failed: \" .. purchaseSkillName .. \" (check level/cash/NPC)\", \"error\", 5)\n    return false\nend\n\nlocal function rodModuleData(rodName)\n    local inventory = Info:FindFirstChild(\"Inventory\")\n    local module = inventory and inventory:FindFirstChild(rodName)\n    if not module then return nil end\n    local ok, value = pcall(require, module)\n    if ok and type(value) == \"table\" then return value end\n    return nil\nend\n\nlocal function hasRecipeIngredients(rodData)\n    if type(rodData) ~= \"table\" or type(rodData.Ingredient) ~= \"table\" then return false, \"no recipe\" end\n    for _, fishName in pairs(rodData.Ingredient) do\n        if type(fishName) == \"string\" and countInventoryFish(fishName) < 1 then\n            return false, \"need \" .. fishName\n        end\n    end\n    return true\nend\n\nlocal ROD_PROGRESSION = {\n    -- Beginning Isle. Steel is skipped for cash efficiency; Ascendant Bamboo remains in the plan\n    -- and is crafted only when Info.Inventory exposes a recipe and every ingredient is present.\n    \"Bamboo Rod\", \"Iron Hook Rod\", \"Enchanted Steel Rod\", \"Ascendant Bamboo Rod\",\n    -- Bamboo / Fallout progression.\n    \"Emerald Rod\", \"Shadow Rod\", \"Triple Steel Rod\", \"Golden Rod\",\n    -- Sovereign / Perch progression.\n    \"Grandmaster Golden Rod\", \"Inferno Rod\", \"Steel Spine Rod\",\n    \"Platinum Spine Rod\", \"Diamond Spine Rod\",\n    -- Frost / Coconut / Amber progression.\n    \"Gravisteel Rod\", \"Inferno Gravity Rod\", \"Cryo Gravity Rod\",\n    \"Thunder Thorn Rod\", \"Soul Thorn Rod\", \"Starlight Rod\",\n    -- Taoist Rod is kept as a late-plan target; craft/quest rods are handled by their own checks.\n    \"Taoist Rod\",\n}\n\n-- SellFish(\"All\") cannot filter individual fish. Protect ingredients only for the next\n-- higher-Power recipe rod in the ordered plan; otherwise AutoSell could sell the exact fish\n-- needed for crafting and the Kaitun would farm/sell that ingredient forever.\nisRodIngredientProtected = function()\n    if not Runtime.enabled then return false end\n    local _, bestPower = getBestOwnedRod()\n    bestPower = tonumber(bestPower) or 0\n    for _, rodName in ipairs(ROD_PROGRESSION) do\n        if not hasRod(rodName) then\n            local info = rodModuleData(rodName)\n            if info and info.Type == \"Fishing Rod\" and type(info.Ingredient) == \"table\"\n                and (tonumber(info.Power) or 0) > bestPower then\n                for _, fishName in pairs(info.Ingredient) do\n                    if type(fishName) == \"string\" and countInventoryFish(fishName) > 0 then\n                        if os.clock() - (Runtime.lastProtectLog or 0) >= 30 then\n                            Runtime.lastProtectLog = os.clock()\n                            log(\"SELL\", \"AutoSell paused to preserve recipe ingredient \" .. fishName .. \" for planned rod \" .. rodName)\n                        end\n                        return true\n                    end\n                end\n                -- Only preserve the next recipe's ingredients, not every future rod recipe.\n                return false\n            end\n        end\n    end\n    return false\nend\n\n-- Verified client contracts in the supplied dump:\n-- BuyFishingRod:FireServer(rodName), EquipFishingRod:InvokeServer(rodName),\n-- CraftRod:FireServer(rodName). Cash/Crystal costs are read only from Info.Inventory.\nlocal function tryBuyProgressionRod()\n    if not Runtime.enabled or isFishingActive() or Runtime.s",
