2355199407.,"tainer and container:FindFirstChild(itemName)\n    if not entry then return false end\n    local owned = entry:FindFirstChild(\"Owned\")\n    if owned and owned:IsA(\"ValueBase\") then return owned.Value == true end\n    if entry:IsA(\"BoolValue\") then return entry.Value == true end\n    return false\nend\n\nlocal function hasRod(rodName)\n    return entryOwned(getRodInventory(), rodName)\nend\n\nlocal function skillVariantRank(candidateName)\n    local candidate = normalized(candidateName)\n    -- Only explicit V1/V2/V3 suffixes indicate a skill version; do not read other trailing digits.\n    local version = tonumber(candidate:match(\"v(%d+)$\"))\n    return version or 1\nend\n\nlocal function skillFamilyKey(skillName)\n    return canonicalSkillKey(skillName):gsub(\"v%d+$\", \"\")\nend\n\nlocal function findSkillEntry(skillName)\n    local folder = getSkillInventory()\n    if not folder then return nil end\n    local wanted = skillFamilyKey(skillName)\n    if wanted == \"\" then return nil end\n    local bestEntry, bestRank, bestOwned = nil, -1, false\n    for _, entry in ipairs(folder:GetChildren()) do\n        local candidate = skillFamilyKey(entry.Name)\n        local matches = candidate == wanted\n        if matches then\n            local owned = entryOwned(folder, entry.Name)\n            local rank = skillVariantRank(entry.Name)\n            if not bestEntry or (owned and not bestOwned) or (owned == bestOwned and rank > bestRank) then\n                bestEntry, bestRank, bestOwned = entry, rank, owned\n            end\n        end\n    end\n    return bestEntry\nend\n\nhasSkill = function(skillName)\n    local folder = getSkillInventory()\n    if not folder then return false end\n    local requested = canonicalSkillKey(skillName)\n    -- In the supplied game dump, Taijiquan V1 is the base module name without a V1 suffix.\n    if requested == \"taijiquantechniquev1\" then\n        for _, entry in ipairs(folder:GetChildren()) do\n            local entryKey = canonicalSkillKey(entry.Name)\n            if entryKey == \"taijiquantechnique\" or entryKey == requested then\n                return entryOwned(folder, entry.Name)\n            end\n        end\n        return false\n    end\n    -- Explicit V2/V3 steps are exact: owning V1 must not mark V2/V3 as owned.\n    if requested:match(\"v%d+$\") then\n        for _, entry in ipairs(folder:GetChildren()) do\n            if canonicalSkillKey(entry.Name) == requested then\n                return entryOwned(folder, entry.Name)\n            end\n        end\n        return false\n    end\n    local entry = findSkillEntry(skillName)\n    return entry ~= nil and entryOwned(folder, entry.Name)\nend\n\nlocal function getOwnedSkillName(skillName)\n    local folder = getSkillInventory()\n    if not folder then return nil end\n    local requested = canonicalSkillKey(skillName)\n    -- Game source names V1 \"Taijiquan Technique\" without the suffix.\n    if requested == \"taijiquantechniquev1\" then\n        for _, entry in ipairs(folder:GetChildren()) do\n            local entryKey = canonicalSkillKey(entry.Name)\n            if (entryKey == \"taijiquantechnique\" or entryKey == requested) and entryOwned(folder, entry.Name) then\n                return entry.Name\n            end\n        end\n        return nil\n    end\n    if requested:match(\"v%d+$\") then\n        for _, entry in ipairs(folder:GetChildren()) do\n            if canonicalSkillKey(entry.Name) == requested and entryOwned(folder, entry.Name) then\n                return entry.Name\n            end\n        end\n        return nil\n    end\n    local wanted = skillFamilyKey(skillName)\n    local bestName, bestRank = nil, -1\n    for _, entry in ipairs(folder:GetChildren()) do\n        local candidate = skillFamilyKey(entry.Name)\n        local matches = candidate == wanted\n        if matches and entryOwned(folder, entry.Name) then\n            local rank = skillVariantRank(entry.Name)\n            if rank > bestRank then bestName, bestRank = entry.Name, rank end\n        end\n    end\n    return bestName\nend\n\nlocal function getSkillModule(skillName)\n    local folder = Info and Info:FindFirstChild(\"Skill\")\n    if not folder then return nil end\n    local exact = folder:FindFirstChild(skillName)\n    if exact then return exact end\n    -- The game dump exposes V1 as \"Taijiquan Technique\" (no suffix).\n    if canonicalSkillKey(skillName) == \"taijiquantechniquev1\" then\n        local baseV1 = folder:FindFirstChild(\"Taijiquan Technique\")\n        if baseV1 then return baseV1 end\n    end\n    -- Never silently replace an unavailable requested V2/V3 module with V1's price/data.\n    if canonicalSkillKey(skillName):match(\"v%d+$\") then return nil end\n    local wanted = skillFamilyKey(skillName)\n    local best, bestRank, bestVersioned = nil, math.huge, true\n    for _, module in ipairs(folder:GetChildren()) do\n        if skillFamilyKey(module.Name) == wanted then\n            local rank = skillVariantRank(module.Name)\n            local versioned = canonicalSkillKey(module.Name):match(\"v%d+$\") ~= nil\n            if not best or rank < bestRank or (rank == bestRank and bestVersioned and not versioned)\n                or (rank == bestRank and bestVersioned == versioned and module.Name < best.Name) then\n                best, bestRank, bestVersioned = module, rank, versioned\n            end\n        end\n    end\n    return best\nend\n\nlocal function getSkillPrice(skillName)\n    local module = getSkillModule(skillName)\n    if not module then return nil end\n    local ok, data = pcall(require, module)\n    if not ok or type(data) ~= \"table\" then return nil end\n    return tonumber(data.Price), data\nend\n\nlocal function readOwnedRodPower(rodName)\n    local inventoryInfo = Info:FindFirstChild(\"Inventory\")\n    local module = inventoryInfo and inventoryInfo:FindFirstChild(rodName)\n    if not module then return 0 end\n    local ok, data = pcall(require, module)\n    if ok and type(data) == \"table\" and data.Type == \"Fishing Rod\" then\n        return tonumber(data.Power) or 0\n    end\n    return 0\nend\n\nlocal function getBestOwnedRod(excludeTaoist)\n    -- Rank by source Power. Non-Pure-Yang builds avoid Taoist Rod on a tie when\n    -- another owned rod is available; Pure Yang Cast gets its explicit rod preference.\n    local folder = getRodInventory()\n    if not folder then return nil, 0 end\n    local bestName, bestPower = nil, -1\n    for _, entry in ipairs(folder:GetChildren()) do\n        local owned = entry:FindFirstChild(\"Owned\")\n        local isTaoist = normalized(entry.Name) == normalized(\"Taoist Rod\")\n        if owned and owned.Value == true and not (excludeTaoist and isTaoist) then\n            local power = readOwnedRodPower(entry.Name)\n            if power > bestPower then bestName, bestPower = entry.Name, power end\n        end\n    end\n    if not bestName and excludeTaoist and hasRod(\"Taoist Rod\") then\n        return \"Taoist Rod\", readOwnedRodPower(\"Taoist Rod\")\n    end\n    return bestName, math.max(0, bestPower)\nend\n\nlocal function getCurrentRodName()\n    local value = UserData and UserData:FindFirstChild(\"FishingRod\")\n    return value and tostring(value.Value or \"\") or \"\"\nend\n\nlocal function getEquippedSkillName(key)\n    local rodName = getCurrentRodName()\n    local rodEntry = getRodInventory() and getRodInventory():FindFirstChild(rodName)\n    local skillSlots = rodEntry and rodEntry:FindFirstChild(\"Skill\")\n    local slot = skillSlots and skillSlots:FindFirstChild(tostring(key))\n    if slot and slot:IsA(\"ValueBase\") and tostring(slot.Value or \"\") ~= \"\" then\n        return tostring(slot.Value)\n    end\n    return nil\nend\n\nlocal function getTraitForSkill(skillName)\n    local skillEntry = findSkillEntry(skillName)\n    if not skillEntry then return \"\" end\n\n    -- Data.Skill entries also contain generic BoolValues such as Owned. Only accept a\n    -- flag whose name exists under Info.Trait, otherwise it can misread Owned=true as\n    -- the skill's trait and incorrectly rank the combo.\n    local traitDefinitions = Info and Info:FindFirstChild(\"Trait\")\n    for _, child in ipairs(skillEntry:GetChildren()) do\n        if child:IsA(\"BoolValue\") and child.Value == true then\n            local hasDefinition = traitDefinitions and traitDefinitions:FindFirstChild(child.Name) ~= nil\n            local targetFallback = normalized(child.Name) == \"azuredragon\" or normalized(child.Name) == \"whitetiger\"\n            if hasDefinition or (not traitDefinitions and targetFallback) then\n                return child.Name\n            end\n        end\n    end\n    return \"\"\nend\n\nlocal function hasDesiredTraitForSkill(skillName)\n    local traitName = normalized(getTraitForSkill(skillName))\n    return traitName == \"azuredragon\" or traitName == \"whitetiger\"\nend\n\nlocal function isDesiredPycTrait()\n    -- Compatibility alias used by older checks; the trait check itself is skill-specific.\n    return hasDesiredTraitForSkill(\"Pure Yang Cast\")\nend\n\n-- Exact secret/priority names are confirmed in ReplicatedStorage.Info.Skill from the supplied game source.\n-- Selection order requested for Isle 9:\n-- 1) Egoless Technique + Azure Dragon/White Tiger\n-- 2) Celestial Gatebreaker + Azure Dragon/White Tiger\n-- 3) Pure Yang Cast + Azure Dragon/White Tiger\n-- 4) Celestial Ape's Heavenbreaker + Azure Dragon/White Tiger\n-- 5) One of the five non-heal Must Have skills; reroll if neither desired trait is found.\nlocal ISLE9_COMBO_PRIORITY = {\n    \"Egoless Technique\",\n    \"Celestial Gatebreaker\",\n    \"Pure Yang Cast\",\n    \"Celestial Ape's Heavenbreaker\",\n}\n\n-- Tier-list fallback #5, after the four named secret/PYC combo anchors above.\n-- Heaven's Restraint is deliberately excluded because it is a sustain/heal skill.\n-- Pure Yang Cast remains handled at priority #3 above, so this list is the other five.\nlocal ISLE9_MUST_HAVE_FALLBACK = {\n    \"Unity with Heaven\",\n    \"Sea Pacifying Needle\",\n    \"Taiji Nine Palaces\",\n    \"Heaven Shatter\",\n    \"Dragon Palace Stomp\",\n}\n\n\n-- End Stage trait priority is one ordered chain: the four combo anchors first, then\n-- the five Must Have fallbacks. A wrong trait on Pure Yang Cast must not bypass the gate.\n-- If an earlier owned skill is locked, or a later priority already has the desired trait,\n-- the system can safely move to the next priority instead of silently farming with a bad one.\nlocal ISLE9_TRAIT_REROLL_PRIORITY = {\n    \"Egoless Technique\",\n    \"Celestial Gatebreaker\",\n    \"Pure Yang Cast\",\n    \"Celestial Ape's Heavenbreaker\",\n    \"Unity with Heaven\",\n    \"Sea Pacifying Needle\",\n    \"Taiji Nine Palaces\",\n    \"Heaven Shatter\",\n    \"Dragon Palace Stomp\",\n}\n\nlocal function getIsle9MustHaveIndex(skillName)\n    local candidate = normalized(skillName)\n    if candidate == \"\" then return nil end\n    for index, baseName in ipairs(ISLE9_MUST_HAVE_FALLBACK) do\n        local base = normalized(baseName)\n        if candidate == base or candidate:sub(1, #base) == base then\n            return index\n        end\n    end\n    return nil\nend\n\nlocal function isIsle9MustHaveFallback(skillName)\n    return getIsle9MustHaveIndex(skillName) ~= nil\nend\n\nlocal function getIsle9ComboIndex(skillName)\n    local candidate = normalized(skillName)\n    if candidate == \"\" then return nil end\n    for index, baseName in ipairs(ISLE9_COMBO_PRIORITY) do\n        local base = normalized(baseName)\n        if candidate == base or candidate:sub(1, #base) == base then\n            return index\n        end\n    end\n    return nil\nend\n\nlocal function isIsle9ComboSkill(skillName)\n    return getIsle9ComboIndex(skillName) ~= nil\nend\n\n-- A skill is allowed in the automatic loadout only if it is owned, explicitly ranked,\n-- a source-confirmed Isle 9 priority anchor, and neither a heal nor a user-excluded skill.\nInternal.isSkillSuitableForAuto = function(skillName)\n    if type(skillName) ~= \"string\" or skillNa",
