log(\"BLOCK\", \"NPC purchase helper is not ready; skipped rod: \" .. rodName)\n                        return false\n                    end\n                    Runtime.lastCraftAttempt = os.clock()\n                    local atNpc, detail = withNPCPurchase(\"BuyFishingRod\", \"Biao Di\", \"BuyFishingRod \" .. rodName, function(atNpc)\n                        if not Runtime.enabled then return false, \"Kaitun stopped before purchase\" end\n                        if hasRod(rodName) then return true, \"already owned\" end\n                        local sent, sendError = fireRemote(\"BuyFishingRod\", rodName)\n                        if not sent then return false, tostring(sendError) end\n\n                        local deadline = os.clock() + (atNpc and 8 or 1.5)\n                        while os.clock() < deadline and Runtime.enabled do\n                            if hasRod(rodName) then return true, \"ownership verified\" end\n                            task.wait(0.25)\n                        end\n                        if hasRod(rodName) then return true, \"ownership verified\" end\n                        return false, \"BuyFishingRod was sent but Owned did not update; seller/price/unlock requirement may have rejected it\"\n                    end)\n\n                    -- Recheck after restoring from the NPC too; a delayed replication can arrive at the boundary.\n                    if atNpc or hasRod(rodName) then\n                        local ownedConfirmed = hasRod(rodName)\n                        if not ownedConfirmed then\n                            local deadline = os.clock() + 2\n                            repeat task.wait(0.2) until hasRod(rodName) or os.clock() >= deadline\n                            ownedConfirmed = hasRod(rodName)\n                        end\n                        if ownedConfirmed then\n                            log(\"STEP\", string.format(\"Rod purchase CONFIRMED: %s (%s %.0f; Power %d)\", rodName, currency, price, tonumber(info.Power) or 0))\n                            Internal.notify(\"Rod purchased: \" .. rodName .. \" \u{2022} Power \" .. tostring(tonumber(info.Power) or 0), \"success\", 4)\n                            local equipped = ensurePreferredRodSelection()\n                            if equipped then\n                                log(\"STEP\", \"Best rod is now selected and held: \" .. tostring(getCurrentRodName()))\n                            else\n                                log(\"BLOCK\", \"Rod is owned, but equip is NOT yet verified: \" .. rodName .. \"; fishing will pause until equip succeeds\")\n                            Internal.notify(\"Rod owned but not equipped: \" .. rodName, \"warning\", 5)\n                            end\n                            return true\n                        end\n                    end\n\n                    log(\"BLOCK\", \"Rod purchase NOT confirmed for \" .. rodName .. \": \" .. tostring(detail or \"Owned flag stayed false\"))\n                    -- One failed request per pass. Do not blindly spam later rods at the same seller.\n                    return false\n                elseif currency and not firstBlocked then\n                    firstBlocked = string.format(\"%.0f %s < %.0f for %s\", tonumber(currency == \"cash\" and cash or crystals) or 0, currency, price, rodName)\n                elseif not currency then\n                    warnOnce(\"rod-no-price-\" .. normalized(rodName), rodName .. \" has no Cash/Crystal price; not sending a guessed purchase request\")\n                end\n            end\n        end\n    end\n\n    if firstBlocked and os.clock() - Runtime.lastRodBlockLog >= 30 then\n        Runtime.lastRodBlockLog = os.clock()\n        log(\"BLOCK\", \"rod purchase waiting: \" .. firstBlocked)\n    end\n    return false\nend\n\nlocal function tryCraftProgressionRod()\n    if not Runtime.enabled or isFishingActive() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false 