hasRod(rodName) then return true, \"ownership verified\" end\n                        return false, \"CraftRod was sent but the crafted rod did not appear in Owned data\"\n                    end)\n                    if atNpc or hasRod(rodName) then\n                        if hasRod(rodName) then\n                            log(\"STEP\", \"Craft confirmed: \" .. rodName)\n                            if not ensurePreferredRodSelection() then\n                                log(\"BLOCK\", \"Crafted rod owned but equip is still pending: \" .. rodName)\n                            end\n                            return true\n                        end\n                    end\n                    log(\"BLOCK\", \"Craft not confirmed for \" .. rodName .. \": \" .. tostring(detail or \"unknown response\"))\n                    return false\n                end\n            elseif missing ~= \"no recipe\" and rodName == ROD_PROGRESSION[1] then\n                log(\"SKIP\", \"Craft \" .. rodName .. \" not ready: \" .. tostring(missing))\n            end\n        end\n    end\n    return false\nend\n\nlocal ISLAND_MIN_POWER = {\n    [1] = 0,\n    [2] = 19, -- Bamboo Isle\n    [3] = 32, -- Fallout Isle\n    [4] = 39, -- Sovereign Isle\n    [5] = 48, -- Perch Isle\n    [6] = 55, -- Frost Isle\n    [7] = 65, -- Coconut Isle\n    [8] = 75, -- Amber Isle\n}\n\nlocal function resolveTargetIsland()\n    local level = getLevel()\n    local _, bestPower = getBestOwnedRod()\n    local currentRodPower = getEquippedRodPower()\n    -- Endgame progression is based on actual level/gear/skills, never a stale island cache.\n    if isEndgameMode() then return 9, \"ENDGAME\" end\n\n    -- Keep the project's conservative early milestone: do not visit Giang Lao/Bamboo before Lv 20.\n    -- Also require the currently equipped rod to satisfy each island's published Power gate.\n    if level < 20 or currentRodPower < ISLAND_MIN_POWER[2] then return 1, \"EARLY\" end\n    if currentRodPower < ISLAND_MIN_POWER[3] then return 2, \"EARLY\" end\n    if currentRodPower < ISLAND_MIN_POWER[4] then return 3, \"MID\" end\n    if currentRodPower < ISLAND_MIN_POWER[5] then return 4, \"MID\" end\n    if currentRodPower < ISLAND_MIN_POWER[6] then return 5, \"MID\" end\n    if currentRodPower < ISLAND_MIN_POWER[7] then return 6, \"LATE\" end\n    if currentRodPower < ISLAND_MIN_POWER[8] then return 7, \"LATE\" end\n    return 8, \"LATE\"\nend\n\nlocal function detectStage()\n    local level = getLevel()\n    local cash = getCash()\n    local rodName, rodPower = getBestOwnedRod()\n    local equippedName = getCurrentRodName()\n    if equippedName ~= \"\" then\n        local equippedPower = readOwnedRodPower(equippedName)\n        if equippedPower > 0 then rodName, rodPower = equippedName, equippedPower end\n    end\n    local heldName = heldRodName()\n    if heldName ~= \"\" then\n        local heldPower = readOwnedRodPower(heldName)\n        if heldPower > 0 then rodName, rodPower = heldName, heldPower end\n    end\n    local skillCount = 0\n    local skillFolder = getSkillInventory()\n    if skillFolder then\n        for _, entry in ipairs(skillFolder:GetChildren()) do\n            local owned = entry:FindFirstChild(\"Owned\")\n            if owned and owned.Value == true then skillCount = skillCount + 1 end\n        end\n    end\n    local target, stage = resolveTargetIsland()\n    if level >= 200 or target == 9 then\n        stage = \"ENDGAME\"\n        persistentState.completed[\"early_bootstrap\"] = true\n        persistentState.completed[\"early_skills\"] = true\n        persistentState.completed[\"mid_rods\"] = true\n        log(\"ENDGAME\", \"ENDGAME DETECTED -> Isle 9\")\n    end\n    return {\n        level = level, cash = cash, rod = rodName or \"None\", rodPower = rodPower,\n        skillCount = skillCount, island = target, stage = stage,\n    }\nend\n\n-- Dialogue is driven through the actual NPC prompt and visible client buttons.\n-- We do not call StartD