"\xFBBT\xF95\xCFu\xA2\x8B:O\x9DH.\x18\x9C\xC71;\xC6\xE5y'\xD9n\xE0\xEAY\xE06R\xD2\x829;6\x85\x88\xF27","                 end\n                    end\n                end\n            end\n        end\n    end\n    return bestName\nend\n\nlocal function equipIsle9Character(primaryName)\n    if not Runtime.enabled or isFishingActive() or Runtime.sellBusy then return false end\n    local actualIsland = select(1, getActualIslandNumber())\n    if actualIsland ~= 9 then return false end\n\n    local folder = UserData and UserData:FindFirstChild(\"PlayerCharacter\")\n    if not folder then\n        warnOnce(\"no-player-character-folder\", \"Data.PlayerCharacter missing; cannot safely verify character ownership\")\n        return false\n    end\n\n    primaryName = primaryName or Runtime.isle9PrimarySkillName\n    -- Prefer Chu Xin on Isle 9 when it is actually owned by this account. This avoids\n    -- choosing a different character just because a selected skill has a different Type.\n    local chuXinEntry = getPlayerCharacterEntry(\"Chu Xin\")\n    local chuXinOwned = chuXinEntry and chuXinEntry:FindFirstChild(\"Owned\")\n    local desiredName\n    if chuXinEntry and chuXinOwned and chuXinOwned.Value == true then\n        desiredName = chuXinEntry.Name\n    else\n        desiredName = primaryName and chooseCharacterForIsle9Skill(primaryName) or nil\n    end\n    if not desiredName then\n        warnOnce(\"no-character-match\", \"Chu Xin is not owned and no owned character boost matched the current skill\")\n        return false\n    end\n\n    local entry = getPlayerCharacterEntry(desiredName)\n    local owned = entry and entry:FindFirstChild(\"Owned\")\n    if not (entry and owned and owned.Value == true) then\n        log(\"SKIP\", \"Recommended character is not owned: \" .. desiredName .. \"; current character will remain equipped\")\n        return false\n    end\n\n    local function confirmed()\n        local flag = entry:FindFirstChild(\"Equip\")\n        return flag ~= nil and flag:IsA(\"ValueBase\") and flag.Value == true\n    end\n    if confirmed() then\n        log(\"STEP\", \"Character equip verified: \" .. desiredName)\n        return true\n    end\n    if os.clock() - Runtime.lastCharacterEquip < 5 then return false end\n    Runtime.lastCharacterEquip = os.clock()\n\n    local ok, result = invokeRemote(\"EquipCharacter\", desiredName)\n    if not ok then\n        log(\"BLOCK\", \"EquipCharacter request failed for \" .. desiredName .. \": \" .. tostring(result))\n        return false\n    end\n    -- InvokeServer completing is not proof that the selected character changed. Wait for\n    -- Data.PlayerCharacter.<name>.Equip to replicate before advancing the loadout.\n    local deadline = os.clock() + 4\n    while Runtime.enabled and os.clock() < deadline do\n        if confirmed() then\n            log(\"STEP\", \"Character equipped and verified: \" .. desiredName .. \" (response=\" .. tostring(result) .. \")\")\n            return true\n        end\n        task.wait(0.2)\n    end\n    log(\"BLOCK\", \"EquipCharacter was requested for \" .. desiredName .. \" but PlayerCharacter.Equip did not confirm it; response=\" .. tostring(result))\n    return false\nend\n\nlocal function orbTypeName(orbEntry)\n    local valueName = orbEntry and orbEntry:FindFirstChild(\"ValueName\")\n    return valueName and tostring(valueName.Value or \"\") or \"\"\nend\n\nlocal function orbData(orbNameOrEntry)\n    local name = typeof(orbNameOrEntry) == \"Instance\" and orbTypeName(orbNameOrEntry) or tostring(orbNameOrEntry or \"\")\n    local folder = Info:FindFirstChild(\"Orb\")\n    local module = folder and folder:FindFirstChild(name)\n    if not module then return nil end\n    local ok, data = pcall(require, module)\n    return ok and type(data) == \"table\" and data or nil\nend\n\nlocal function isOrbOwned(orbEntry)\n    -- Data.Orb has per-item instance IDs; ValueName points to Info.Orb's module.\n    return orbEntry ~= nil and orbEntry:FindFirstChild(\"ValueName\") ~= nil and orbData(orbEntry) ~= nil\nend\n\nlocal function isOrbEquipping(orbId)\n    local folder = UserData and UserData:FindFirstChild(\"Orb\")\n    local entry = folder and folder:FindFirstChild(tostring(orbId))\n    local value = entry and entry:FindFirstChild(\"Equipping\")\n    return value and value.Value == true or false\nend\n\nlocal function orbStat(orbEntry, statName, maximumName, minimumName)\n    local current = numericValue(orbEntry and orbEntry:FindFirstChild(statName))\n    if current ~= nil then return current end\n    local data = orbData(orbEntry)\n    if data then\n        return ((tonumber(data[maximumName]) or 0) + (tonumber(data[minimumName]) or 0)) / 2\n    end\n    return 0\nend\n\nlocal function orbScore(orbEntry)\n    local data = orbData(orbEntry)\n    if not data then return -math.huge end\n    local damage = orbStat(orbEntry, \"Damage\", \"MaxDamage\", \"MinDamage\")\n    local cooldown = orbStat(orbEntry, \"Cooldown\", \"MaxCooldown\", \"MinCooldown\")\n    local luck = orbStat(orbEntry, \"Luck\", \"MaxLuck\", \"MinLuck\")\n    local drop = orbStat(orbEntry, \"Drop\", \"MaxDrop\", \"MinDrop\")\n    local cash = orbStat(orbEntry, \"Cash\", \"MaxCash\", \"MinCash\")\n    local score = damage * 1.5 + cooldown * 1.25 + luck * 0.35 + drop * 0.1 + cash * 0.08\n    return score\nend\n\nlocal function orbDisplayName(orbId)\n    local folder = UserData and UserData:FindFirstChild(\"Orb\")\n    local entry = folder and folder:FindFirstChild(tostring(orbId))\n    local valueName = orbTypeName(entry)\n    return valueName ~= \"\" and valueName or tostring(orbId)\nend\n\nlocal function getBestOwnedOrbs()\n    local folder = UserData and UserData:FindFirstChild(\"Orb\")\n    local ranked = {}\n    if folder then\n        for _, entry in ipairs(folder:GetChildren()) do\n            if isOrbOwned(entry) then\n                local score = orbScore(entry)\n                if score > -math.huge then\n                    table.insert(ranked, {id = entry.Name, name = orbTypeName(entry), score = score})\n                end\n            end\n        end\n    end\n    table.sort(ranked, function(a, b)\n        if a.score == b.score then return a.id < b.id end\n        return a.score > b.score\n    end)\n    local result = {}\n    for i = 1, math.min(2, #ranked) do result[#result + 1] = ranked[i] end\n    return result, ranked\nend\n\nlocal function getCurrentRodOrbSlots(rodName)\n    local result = {}\n    local rod = getRodInventory() and getRodInventory():FindFirstChild(rodName or getCurrentRodName())\n    local orbFolder = rod and rod:FindFirstChild(\"Orb\")\n    for _, slotName in ipairs({\"Slot1\", \"Slot2\"}) do\n        local value = orbFolder and orbFolder:FindFirstChild(slotName)\n        result[#result + 1] = value and tostring(value.Value or \"\") or \"\"\n    end\n    return result\nend\n\nlocal function getOrbPlanForPrimary(primaryName)\n    local _, ranked = getBestOwnedOrbs()\n    ranked = ranked or {}\n    local plan, usedIds = {}, {}\n\n    local function addItem(item)\n        if not item or #plan >= 2 then return false end\n        local key = normalized(item.id)\n        if key == \"\" or usedIds[key] then return false end\n        usedIds[key] = true\n        plan[#plan + 1] = item\n        return true\n    end\n    local function addNamed(orbName)\n        local wanted = normalized(orbName)\n        for _, item in ipairs(ranked) do\n            if normalized(item.name) == wanted then return addItem(item) end\n        end\n        return false\n    end\n    local function addBest(excludedName)\n        local excluded = normalized(excludedName)\n        for _, item in ipairs(ranked) do\n            if (excluded == \"\" or normalized(item.name) ~= excluded) and not usedIds[normalized(item.id)] then\n                return addItem(item)\n            end\n        end\n        return false\n    end\n\n    local n = normalized(primaryName)\n    local preferredOrb = nil\n    local useMythPair = false\n    if n:find(\"egolesstechnique\", 1, true) == 1 then\n        preferredOrb = \"Execution Orb\"\n    elseif n:find(\"celestialapesheavenbreaker\", 1, true) == 1\n        or n:find(\"celestialgatebreaker\", 1, true) == 1 then\n        preferredOrb = \"So Tam Orb\"\n    elseif n:find(\"pureyangcast\", 1, true) == 1 then\n        preferredOrb = \"Taoist Orb\"\n    elseif isIsle9MustHaveFallback(primaryName) and not (n:find(\"taijininepalaces\", 1, true) == 1) then\n        useMythPair = true\n    end\n\n    if preferredOrb then\n        local foundPreferred = addNamed(preferredOrb)\n        if foundPreferred then addBest(preferredOrb) end\n        if not foundPreferred then\n            addBest(\"\")\n            addBest(\"\")\n        end\n    elseif useMythPair then\n        -- Best general orb first; if owned, pair it with Myth Orb as requested.\n        local hasMyth = false\n        for _, item in ipairs(ranked) do\n            if normalized(item.name) == normalized(\"Myth Orb\") then hasMyth = true; break end\n        end\n        if hasMyth then\n            addBest(\"Myth Orb\")\n            addNamed(\"Myth Orb\")\n            if #plan < 2 then addBest(\"\") end\n        else\n            addBest(\"\")\n            addBest(\"\")\n        end\n    else\n        addBest(\"\")\n        addBest(\"\")\n    end\n\n    -- Fill an open slot from the remaining inventory if a requested special orb was the\n    -- only orb type available. IDs must remain unique; the server toggles inventory IDs.\n    if #plan < 2 then addBest(\"\") end\n    return plan\nend\n\nlocal function equipBestOrbs(primaryName)\n    if isFishingActive() then return false end\n    local rodName = getCurrentRodName()\n    if rodName == \"\" then return false end\n    primaryName = primaryName or Runtime.isle9PrimarySkillName\n    local desired = getOrbPlanForPrimary(primaryName)\n    if #desired == 0 then\n        warnOnce(\"no-owned-orbs\", \"No owned orb instances with a valid ValueName/Info.Orb module; leaving slots unchanged\")\n        return false\n    end\n    local current = getCurrentRodOrbSlots(rodName)\n    local same = true\n    for i = 1, 2 do\n        if normalized(current[i]) ~= normalized(desired[i] and desired[i].id or \"\") then same = false end\n    end\n    if same then return true end\n    if os.clock() - Runtime.lastOrbLoadout < 10 then return false end\n    Runtime.lastOrbLoadout = os.clock()\n    local targetSet = {}\n    for _, item in ipairs(desired) do targetSet[normalized(item.id)] = true end\n    local seenCurrent = {}\n    for _, orbId in ipairs(current) do\n        local nId = normalized(orbId)\n        if orbId ~= \"\" and not targetSet[nId] and not seenCurrent[nId] and isOrbEquipping(orbId) then\n            seenCurrent[nId] = true\n            local ok, result = invokeRemote(\"EquipOrb\", orbId)\n            if ok and result then log(\"STEP\", \"Unequip orb not in selected plan: \" .. orbDisplayName(orbId))\n            else log(\"BLOCK\", \"Orb toggle rejected for \" .. orbDisplayName(orbId) .. \": \" .. tostring(result)) end\n            task.wait(0.2)\n        end\n    end\n    for _, item in ipairs(desired) do\n        local orbId = item.id\n        local stillInSlot = false\n        for _, currentId in ipairs(getCurrentRodOrbSlots(rodName)) do\n            if normalized(currentId) == normalized(orbId) then stillInSlot = true end\n        end\n        if not stillInSlot then\n            local wasEquippedElsewhere = isOrbEquipping(orbId)\n            local ok, result = invokeRemote(\"EquipOrb\", orbId)\n            if ok and result and wasEquippedElsewhere then\n                log(\"STEP\", \"Orb was assigned elsewhere; toggled it off first and will retry next pass: \" .. item.name)\n            elseif ok and result then\n                log(\"STEP\", string.format(\"EquipOrb accepted: %s [%s], score %.1f\", item.name, orbId, item.score))\n            else\n                log(\"BLOCK\", \"EquipOrb failed for \" .. item.name .. \": \" .. tostring(result))\n            end\n            task.wait(0.25)\n        end\n    end\n    local finalSlots = getCurrentRodOrbSlots(rodName)\n    local d1 = desired[1] and (desired[1].name .. \" [\" .. desired[1].id .. \"]\") or \"none\"\n    local d2 = desired[",
